<script setup>
import { onMounted,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { api,send,money } from '../api'
const rows=ref([]),quote=ref(null),currency=ref('USD'),country=ref('US'),recipient=ref(''),address=ref(''),error=ref(''),busy=ref(false),loading=ref(true),router=useRouter()
let requestKey=crypto.randomUUID(),quoteVersion=0
async function refreshQuote(){const version=++quoteVersion;quote.value=null;try{const value=await api(`/quote?currency=${currency.value}&country=${country.value}`);if(version===quoteVersion)quote.value=value}catch(e){if(version===quoteVersion)error.value=e.message}}
async function load(){error.value='';try{rows.value=await api('/cart');await refreshQuote()}catch(e){error.value=e.message}finally{loading.value=false}}
async function update(row,quantity){if(busy.value)return;busy.value=true;error.value='';try{await api('/cart/'+row.id,send('PUT',{quantity}));requestKey=crypto.randomUUID();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function checkout(){busy.value=true;error.value='';try{await api('/orders',send('POST',{requestKey,currency:currency.value,country:country.value,recipient:recipient.value,address:address.value}));router.push('/orders')}catch(e){error.value=e.message}finally{busy.value=false}}
watch([currency,country],()=>{requestKey=crypto.randomUUID();refreshQuote()})
onMounted(load)
</script>
<template><section class="page"><div class="page-title"><div><p class="subtle">YOUR EVERYDAY FINDS</p><h1>购物车</h1></div><RouterLink to="/">继续选购 ↗</RouterLink></div><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="loading" class="empty">正在载入购物车…</p><div v-else-if="!rows.length" class="empty"><h2>购物车还没有好物。</h2><p>去挑一件陪伴日常的小物吧。</p><RouterLink to="/" class="button">探索商品</RouterLink></div><div v-else class="checkout-grid"><div><article v-for="row in rows" :key="row.id" class="cart-row"><img :src="row.image" :alt="row.name"><div class="cart-info"><p class="subtle">{{row.category}}</p><h3>{{row.name}}</h3><p>{{money(row.price)}} / 件（基准价）</p><div class="quantity"><button :disabled="busy||row.quantity<=1" @click="update(row,row.quantity-1)" :aria-label="'减少 '+row.name">−</button><span>{{row.quantity}}</span><button :disabled="busy||row.quantity>=99||row.quantity>=row.stock" @click="update(row,row.quantity+1)" :aria-label="'增加 '+row.name">＋</button></div></div><button class="text-button" :disabled="busy" @click="update(row,0)">移除</button></article><p class="fine-print">购物车不预占库存；下单时会再次校验价格和可售库存。</p></div><form class="checkout-summary" @submit.prevent="checkout"><h2>配送与结算</h2><div class="form-two"><label>配送国家<select v-model="country" :disabled="busy"><option value="US">美国</option><option value="DE">德国</option><option value="GB">英国</option></select></label><label>结算币种<select v-model="currency" :disabled="busy"><option>USD</option><option>EUR</option><option>GBP</option></select></label></div><label>收件人<input v-model="recipient" required maxlength="80" autocomplete="name"></label><label>完整地址<textarea v-model="address" required maxlength="500" rows="3" autocomplete="street-address" placeholder="街道、城市、州/省与邮编"></textarea></label><template v-if="quote"><dl class="totals"><div><dt>商品小计</dt><dd>{{money(quote.subtotal,currency)}}</dd></div><div><dt>跨境运费</dt><dd>{{Number(quote.shipping)===0?'免运费':money(quote.shipping,currency)}}</dd></div><div class="total"><dt>订单合计</dt><dd>{{money(quote.total,currency)}}</dd></div></dl></template><p v-else>正在更新报价…</p><p class="fine-print">满 US$100 免运费；固定演示汇率，不含进口关税。下单后可在订单页模拟付款。</p><button class="button full" :disabled="busy||!quote">{{busy?'提交中…':'创建订单 →'}}</button></form></div></section></template>
